<script type="module">
import * as THREE from 'three';

// ---------- palette taken from the print ----------
const C = {
  deepBlue: 0x16436b,
  midBlue:  0x2f6a94,
  lightBlue:0x87b7d4,
  foam:     0xf2efe6,
  cream:    0xe8e0cd,
  skyPink:  0xdcc4b2,
  horizon:  0x8a8578,
  hullTan:  0xc9a878,
  rowerBlue:0x27506e,
  fujiBlue: 0x3d5a75,
  snow:     0xf5f2ea
};

// ---------- renderer / scene / camera ----------
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xd8cfbf, 34, 78);

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 300);
camera.position.set(0, 3.6, 17.5);
camera.lookAt(0, 3.2, 0);

const hemi = new THREE.HemisphereLight(0xf0e8d8, 0x2a4a66, 0.9);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff2dc, 1.6);
sun.position.set(-6, 12, 8);
scene.add(sun);

const flatMat = (color, extra = {}) =>
  new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 1, metalness: 0, ...extra });

// ---------- sky: vertex-colored gradient plane (cream top -> pale pink -> grey) ----------
{
  const g = new THREE.PlaneGeometry(240, 140, 1, 10);
  const pos = g.attributes.position;
  const colors = [];
  const top = new THREE.Color(0xe8e0cd), mid = new THREE.Color(0xdcc4b2), bot = new THREE.Color(0x9a9587);
  for (let i = 0; i < pos.count; i++) {
    const y = pos.getY(i); // -70..70
    const t = (y + 70) / 140; // 0 bottom .. 1 top
    const c = t > 0.5 ? mid.clone().lerp(top, (t - 0.5) * 2) : bot.clone().lerp(mid, t * 2);
    colors.push(c.r, c.g, c.b);
  }
  g.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  const sky = new THREE.Mesh(g, new THREE.MeshBasicMaterial({ vertexColors: true, fog: false }));
  sky.position.set(0, 30, -90);
  scene.add(sky);
}

// ---------- horizon bokashi band (dark grey gradient behind Fuji) ----------
{
  const band = new THREE.Mesh(new THREE.PlaneGeometry(160, 7),
    new THREE.MeshBasicMaterial({ color: C.horizon, transparent: true, opacity: 0.45, fog: false }));
  band.position.set(0, 3.4, -60);
  scene.add(band);
  const band2 = new THREE.Mesh(new THREE.PlaneGeometry(160, 2.4),
    new THREE.MeshBasicMaterial({ color: 0x6b6558, transparent: true, opacity: 0.5, fog: false }));
  band2.position.set(0, 1.9, -59);
  scene.add(band2);
}

